registerRefData('nsw-cond-n-7382',{"id":7382,"pan":null,"ref":"10.2016.143.7","address":"131 Parramatta Rd, Homebush 2140 NSW","description":"Demolition of existing structures and construction of a seven (7) storey mixed use development comprising of (40) residential units and four (4) retail tenancies above four (4) retail tenancies above four (4) levels of basement carparking.","outcome":"approved","outcome_raw":"Approved - Delegation","outcome_source":"tracker","determined":"2024-05-03","notice_url":"https://datracker.strathfield.nsw.gov.au/document/download?key=sqYrCrSWWL0=&fileName=DA2016.143.7 - 131 Parramatta Road HOMEBUSH - Notice of Determination (Signed).PDF","sha256":"4566827d5b4799181eb912fc761c8697cd9298e891c43977c3bf706113951095","pages":48,"layout":"numbered","n":10,"fetched_at":"2026-08-17T06:57:38+00:00","file":"n/7382.js","source_page":"https://datracker.strathfield.nsw.gov.au/Application/ApplicationDetails/010.2016.00000143.007","lga":"STRATHFIELD","conditions":[{"label":"1","code":null,"number":"1","title":"May 2024","text":"A 00.001 Basix\nCommitments\nGhazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023","stage":"general","stage_basis":"heading","page":6},{"label":"4","code":null,"number":"4","title":"January","text":"2024\nA00.001A Basix\nCommitments\nGhazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA00.002 Unit Type\nSchedule\nGhazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA02.001 Basement 04\nPlan\nGhazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA02.002 Basement 03\nPlan\nGhazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA02.003 Basement 02\nPlan\nGhazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA02.004 Basement 01\nPlan\nGhazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA02.005 Ground Floor\nPlan\nGhazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA02.006 Level 01 Plan Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA02.007 Level 02 Plan Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA02.008 Level 03 Plan Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA02.009 Level 04 Plan Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA02.010 Level 05 Plan Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA02.011 Level 06 Plan Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA02.012 Roof Plan Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA03.001 North Elevation Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nB 1 May 2024","stage":"general","stage_basis":"heading","page":6},{"label":"1","code":null,"number":"1","title":"May 2024","text":"A03.002 East Elevation Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nB 1 May 2024","stage":"general","stage_basis":"heading","page":7},{"label":"1","code":null,"number":"1","title":"May 2024","text":"A03.003 South Elevation Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nB 1 May 2024","stage":"general","stage_basis":"heading","page":7},{"label":"1","code":null,"number":"1","title":"May 2024","text":"A03.004 West Elevation Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nB 1 May 2024","stage":"general","stage_basis":"heading","page":7},{"label":"1","code":null,"number":"1","title":"May 2024","text":"A03.101 Material\nSchedule -\nNorth & East\nGhazi Al Ali\nArchitect\nSection S4.55 - Issue\nB 1 May 2024","stage":"general","stage_basis":"heading","page":7},{"label":"1","code":null,"number":"1","title":"May 2024","text":"A03.102 Material\nSchedule -\nSouth & West\nGhazi Al Ali\nArchitect\nSection S4.55 - Issue\nB 1 May 2024","stage":"general","stage_basis":"heading","page":7},{"label":"1","code":null,"number":"1","title":"May 2024","text":"A04.001 Section A-A Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023","stage":"general","stage_basis":"heading","page":7},{"label":"4","code":null,"number":"4","title":"January","text":"2024\nA04.002 Section B-B Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nA04.003 Section C-C Ghazi Al Ali\nArchitect\nSection S4.55 - Issue\nA 26 October 2023\n4 January\n2024\nLPS455\n16-467/1\nTitle Page Conzept\nLandscape\nArchitects\nIssue G, 24 May 2023 4 January\n2024\nLPS455\n16-467/1\nLandscape Plan\n- Ground\nConzept\nLandscape\nArchitects\nIssue G, 24 May 2023 4 January\n2024\nLPS455\n16-467/1\nLandscape Plan\n- L1-L5\nConzept\nLandscape\nArchitects\nIssue G, 24 May 2023 4 January\n2024\nLPS455\n16-467/1\nLandscape Plan\n- L6\nConzept\nLandscape\nArchitects\nIssue G, 24 May 2023 4 January\n2024\nLPS455\n16-467/1\nIrrigation Plan Conzept\nLandscape\nArchitects\nIssue G, 24 May 2023 4 January\n2024\nLPS455\n16-467/1\nDetails &\nSpecifications\nConzept\nLandscape\nArchitects\nIssue G, 24 May 2023 4 January\n2024\nLPS455\n16-467/1\nPlanter on Slab\nDetail\nConzept\nLandscape\nArchitects\nIssue G, 24 May 2023 4 January\n2024\nLPS455\n16-467/1\nPergola and\nTrellis Detail\nConzept\nLandscape\nArchitects\nIssue G, 24 May 2023 4 January\n2024\nSW02 Stormwater\nBasement Floor\nSGC\nEngineering\nD 17 March 2017\nSW03 Stormwater\nGround Floor\nSGC\nEngineering\nD 17 March 2017\nSW04 Stormwater Roof SGC\nEngineering\nD 17 March 2017\nSW05 Stormwater\nDetails Sheet\nSGC\nEngineering\nD 17 March 2017\nSW06 Erosion &\nSediment Control\nSGC\nEngineering\nD 17 March 2017\nMODIFIED: DA2016.143.6 3 May 2024\nReference Documentation affixed with Council’s ‘Development Consent’ stamp\nrelating to Development Consent No. 2016/143.\nTitle/Description Prepared by Issue/Revision &\nDate\nDate received\nby Council\nNoise Assessment Acoustic Consulting\nEngineers Pty Ltd\n160732-01 L-DD\n16 September\n2016\nBASIX Certificate Sustainable Thermal\nSolutions\nNo. 728695M_03\nissued on 25\nOctober 2023\n4 January\n2024\nDisability Access\nReport\nAccess Solutions\nNSW Pty Ltd\nA 16 September\n2016\nTraffic & Parking\nAssessment\nParking & Traffic\nConsultants\nRefT2-1650,\n16 September\n2016\nStage 1 Preliminary\nEnvironmental Site\nInvestigation\nGeo-Environmental\nEngineering\nG16043HOM-R02F\n27 June 2016\n16 September\n2016\nPreliminary\nGeotechnical\nInvestigation Report\nGeo-Environmental\nEngineering\nG16043HOM-R01F","stage":"general","stage_basis":"heading","page":7},{"label":"7","code":null,"number":"7","title":"July 2016","text":"16 September\n2016\nGeotechnical\nInvestigation\nGeo-Environmental\nEngineering\nG16043HOM-R03F\n25 August 2016\n16 September\n2016\nStage 2 Detailed Site\nInvestigation\nGeo-Environmental\nEngineering\nG16043HOM-R03F\n7 February 2017\n15 February\n2017\nBCA Report Design Right\nConsulting\n5 July 2016 16 September\n2016\nWaste Management\nPlan\nGhazi Al Ali\nArchitect\nSeptember 2023 4 January\n2024\nMODIFIED: DA2016.143.6 3 May 2024\nIn the event of any inconsistency between the approved plans and supplementary\ndocumentation, the plans will prevail. However, the conditions of this consent shall\nprevail to the extent of any inconsistency.\n(Reason: To ensure that the form of the development undertaken is in accordance\nwith the determination of Council)\nDAGC002 Approval (separate approval required)\nThis consent does not include approval for the fit out and/ or use of the\nground floor commercial tenancies. Separate development consent shall be\nobtained for the fit out and use of the tenancies\n(Reason: To control future development of the site)\nDAGC005 Building height (maximum RL to be complied with)\nThe height of the building measured to Australian Height Datum (AHD) must\nnot exceed Relative Level (RL) 33.07 AHD to the corner roof element of the\nbuilding.\n(Reason: To ensure the approved building height is complied with)\nMODIFIED: DA2016.143.6 3 May 2024\nDAGC007 Construction hours\nNo construction or any other work related activities shall be carried out on the\nsite outside the hours of 7.00 am to 5.00 pm Mondays to Fridays and Sam to\n1pm Saturdays.\nNo building activities are to be carried out at any time on a Sunday or public\nholiday.\nWhere the development involves the use of jackhammers/ rock breakers\nand the like or other heavy machinery, such equipment may only be used\nbetween the hours of 7.00 am - 5.00 pm Monday to Friday only.\n(Reason: To maintain amenity to adjoining landowners)\nDAGC008 Construction within boundaries\nThe development including but not limited to footings, walls, roof barges and\nguttering must be constructed wholly within the boundary of the premises. No\nportion of the proposed structure shall encroach onto the adjoining properties.\nGates must be installed so they do not open onto any footpath or adjoining\nland.\n(Reason: Approved works are to be contained wholly within the subject site).\nDAGC011 Demolition (site safety fencing)\nSite fencing is to be erected to a minimum height of 1.8m complying with\nWorkCover Guidelines, to exclude public access to the site, prior to any\ndemolition works occurring and maintained for the duration of the demolition\nworks.\nIf applicable, a separate Hoarding Application for the erection of an A\nclass (fence type) or B class (overhead type) hoarding along the street frontage(s)\ncomplying with WorkCover requirements must be obtained including:\n(i) payment to Council of a footpath occupancy fee based on the area of\nfootpath to be occupied and Council's Schedule of Fees and Charges\nbefore the commencement of work; and\n(ii) provision of a Public Risk Insurance Policy with a minimum cover of\n$10 million in relation to the occupation of and works within Council's\nroad reserve, for the full duration of the proposed works, must be\nobtained with a copy provided to Council.\n(Reasons: Statutory requirement and health and safety)\nDAGC013 Fencing (front fence height)\nSolid fencing forward of the building line (including the building line to a\nsecondary street frontage on a corner site) shall not exceed a height of 1 m\nabove natural ground level.\n(Reason: To ensure a positive contribution to the streetscape in accordance\nwith the Strathfield Consolidated DCP 2005)\nDAGC015 Landscaping\nA minimum of five (5) x Ceratopetalum gummiferum (NSW Christmas Bush),\nBanksia integrifolia (Coastal Banksia), Pittosporum rhombifolium (Diamond\nleaved Pittosporum), Elaeocarpus eumundii (Smooth leaved Quandong),\nStenocarpus sinuatus (Qld Firewheel tree) or Buckinghamia celissima (Ivory\nCurl) shall be provided in raised planter beds along the site's Park Road\nfrontage. Such trees shall be a minimum 50 litre container size and shall be\nmaintained until maturity.\n(Reason: Privacy amenity of adjoining properties)\nDAGC016 Landscaping (canopy trees in front setback)\nA minimum of one (1) x Ceratopetalum apetalum (Coachwood) or Backhousia\ncitriodora (Lemon scented myrtle) replacement tree shall be provided in each\nof the three (3) deep soil areas adjacent to the site’s northern boundary. New\ncanopy trees shall be at least three (3) metres high at the time of planting and\ncapable of reaching a mature height of 10m.\nCompliance with this condition is to be demonstrated to the Principal Certifying\nAuthority, prior to the issue of any Occupation Certificate.\n(Reason: To ensure the landscape character of the locality is maintained)\nDAGC017 Landscaping (irrigation of common and private landscape\nareas)\nAll common and private landscape areas including all planters are to have full\ncoverage by a fully automatic irrigation system. The design, materials and\ninstallation are to be in accordance with Sydney Water Codes and satisfy all\nrelevant Australian Standards. Details demonstrating compliance shall be\nsubmitted to the Principal Certifying Authority, prior occupation of the\npremises.\n(Reason: To ensure appropriate landscape maintenance)\nDAGC018 Landscaping (trees permitted to be removed)\nThe following listed trees are permitted to be removed to accommodate the\nproposed development:\nTree No. in Arborist\nReport\nTree Location\nCinnamomum camphora\n(Camphor laurel)\n12 x 5 Park Road Setback\nCinnamomum camphora\n(Camphor laurel)\n12 x 5 Park Road Setback\nAll trees permitted to be removed by this consent shall be replaced by species\nselected from Council's Recommended Tree List.\nReplacement trees shall be a minimum 50 litre container size. Trees are to\nconform to the NATSPEC guide and Guide for assessing the quality of and\npurchasing of landscape trees by Ross Clarke, 2003. Trees are to be true to\ntype, healthy and vigorous at time of delivery and planting, shall be pest and\ndisease free, free from injury and wounds and self-supporting; and shall be\nmaintained until maturity.\nAll trees are to be staked and tied with a minimum of three (3) hardwood\nstakes. Ties are to be hessian and fixed firmly to the stakes, one tie at half the\nheight of the main stem, others as necessary to stabilise the plant.\nRoot deflection barriers having a minimum depth of 600mm are to be installed\nadjacent to all footpaths and driveways.\nSoil conditioner/fertilizer/moisture retention additive/s are to be applied in\naccordance with manufacturer's recommendations, and mixed into the\nbackfilling soil after planting tree/s.\nA minimum 75mm depth of organic mulch shall be placed within an area 0.5m\nfrom the base of the tree.\nDetails demonstrating compliance shall be demonstrated to the Principal\nCertifying Authority, prior to the issue of any Occupation Certificate.\n(Reason: To ensure appropriate planting back onto the site)\nDAGC021 Lighting\nAny lighting of the premises shall be installed and maintained in accordance\nwith Australian Standard AS 4282-1997: Control of the Obtrusive Effects of\nOutdoor Lighting so as to avoid annoyance to the occupants of adjoining\npremises or glare to motorists on nearby roads.\nNo flashing, moving or intermittent lighting, visible from any public place may\nbe installed on the premises or external signage associated with the\ndevelopment, without the prior approval of Council.\n(Reason: To protect the amenity of surrounding development and protect\npublic safety)\nDAGC022 Materials (external materials and reflectivity)\nAll external materials, colours and finishes including windows and doors and\nroofing materials must be of high quality and compatible with those of the\nsurrounding streetscape and locality. All external materials and colours shall\nbe of low glare and reflectivity. Details demonstrating compliance with this\ncondition, shall be provided to the Principal Certifying Authority, prior to the\nissue of any Construction Certificate.\n(Reason: To ensure a positive contribution to the streetscape and to minimise\nexcessive glare and reflectivity)\nDAGC023 Materials (schedule of external materials, finishes and\ncolours)\nThe external materials, finishes and colours are to be consistent with the schedule\nsubmitted and approved by Council with the development application.\n(Reason: To ensure compliance with this consent)\nDAGC024 Principal certifying authority (PCA) identification sign\nPrior to commencement of any work, signage must be erected in a prominent\nposition on the work site identifying:\n(i) the Principal Certifying Authority (PCA) by showing the name,\naddress and telephone number of the PCA;\n(ii) the Principal Contractor by showing the Principal Contractor's name,\naddress and telephone number (outside of work hours) for that\nperson; and\n(iii) the sign must state that unauthorised entry to the work site is\nprohibited.\nAny such sign is to be maintained while the work is being carried out, but\nmust be removed when the work has been completed.\nThis clause does not apply to building work, subdivision work or demolition\nwork that is carried out inside an existing building that does not affect the\nexternal walls of the building.\n(Reason: Statutory requirement)\nDAGC027 Site management (during demolition and construction\nworks)\nAll of the following are to be satisfied/complied with during demolition,\nconstruction and any other site works:\n(i) All demolition is to be carried out in accordance with Australian\nStandard AS 2601-2001.\n(ii) Demolition must be carried out by a registered demolition contractor.\n(iii) A single entrance is permitted to service the site for demolition and\nconstruction. The footway and nature strip at the service entrance\nmust be planked out.\n(iv) No blasting is to be carried out at any time during construction of the\nbuilding.\n(v) Care must be taken during demolition/ excavation/ building/\nconstruction to prevent any damage to adjoining buildings.\n(vi) Adjoining owner property rights and the need for owner's permission\nmust be observed at all times, including the entering onto land for the\npurpose of undertaking works.\n(vii) Any demolition and excess construction materials are to be recycled\nwherever practicable.\n(viii) The disposal of construction and demolition waste must be in\naccordance with the requirements of the Protection of the\nEnvironment Operations Act 1997.\n(ix) All waste on the site is to be stored, handled and disposed of in such\na manner as to not create air pollution (including odour), offensive\nnoise or pollution of land and/or water as defined by the Protection of\nthe Environment Operations Act 1997. All excavated material should\nbe removed from the site in an approved manner and be disposed of\nlawfully to a tip or other authorised disposal area.\n(x) All waste must be contained entirely within the site.\n(xi) Section 143 of the Protection of the Environment Operations Act\n1997 requires waste to be transported to a place which can lawfully\naccept it. All non-recyclable demolition materials are to be disposed\nof at an approved waste disposal depot in accordance with\nlegislation.\n(xii) All materials on site or being delivered to the site are to generally be\ncontained within the site. The requirements of the Protection of -the\nEnvironment Operations Act 1997 must be complied with when\nplacing/stockpiling loose material, disposing of concrete waste, or\nother activities likely to pollute drains or water courses.\n(xiii) Details as to the method and location of disposal of demolition\nmaterials (weight dockets, receipts, etc.) should be kept on site as\nevidence of approved methods of disposal or recycling.\n(xiv) Any materials stored on site must be stored out of view or in such a\nmanner so as not to cause, unsightliness when viewed from nearby\nlands or roadways.\n(xv) Public footways and roadways adjacent to the site must be\nmaintained and cleared of obstructions during construction. No\nbuilding materials, waste containers or skips may be stored on the\nroad reserve or footpath without prior separate approval from\nCouncil, including payment of relevant fees.\n(xvi) Building operations such as brick-cutting, washing tools or paint\nbrushes, and mixing mortar not be performed on the roadway or\npublic footway or any other locations which could lead to the\ndischarge of materials into the stormwater drainage system.\n(xvii) All site waters during excavation and construction must be contained\non site in an approved manner to avoid pollutants entering into\nwaterways or Council's stormwater drainage system.\n(xviii) Any work must not prohibit or divert any natural overland flow of\nwater.\n(xix) Toilet facilities for employees must be provided in accordance with\nWorkCover NSW.\n(xx) Protection pads are to be installed to the kerb and gutter where\ntrucks and vehicles enter the site.\n(Reason: To ensure that demolition, building and any other site works are\nundertaken in accordance with relevant legislation and policy and in a manner\nwhich will be non-disruptive to the local area)\nDAGC028 Stormwater management plan (certification requirement)\nA detailed Stormwater Management Plan (SWMP) in line with Council's Stormwater\nManagement Code is to be prepared and certified by a practicing Chartered\nProfessional Engineer on the National Professional Engineer's Register (NPER) at\nEngineers Australia and submitted to the Principal Certifying Authority and Council,\nprior to the issue of a Construction Certificate. The SWMP is to be based on the\napproved development as modified by any conditions of consent.\n(Reason: To ensure appropriate provision is made for the disposal and management\nof stormwater generated by the development, and to ensure public infrastructure in\nCouncil's care and control is not overloaded)\nDAGC029 Sydney Water (stamped plans prior to commencement)\nThe approved plans must be submitted to a Sydney Water Quick Check agent or\nCustomer Centre to determine whether the development will affect Sydney Water's\nsewer and water mains, stormwater drains and/or easements, and if further\nrequirements need to be met. Plans will be appropriately stamped.\nFor Quick Check agent details please refer to the web site www.sydneywater.com.au\n(see Building Developing and Plumbing then Quick Check) or telephone 13 20 92.\nThe consent authority or a Certifying Authority must ensure that a Quick Check\nagent/Sydney Water has stamped the plans before the commencement of work.\n(Reason: Compliance with Sydney Water requirements)\nDAGC030 Utilities and services (protection of)\nAny footings or excavation to be located or undertaken adjacent to Council's\nstormwater must be designed to address the following requirements:\n(i) all footings and excavation must be located wholly within the site and\nclear of any easement boundaries;\n(ii) all footings and excavation must be located a minimum of 1000mm\nfrom the centreline of the pipeline or 500mm from the outside of the\npipeline, whichever is the greater distance from the centreline; and\n(iii) footings must extend to at least the depth of the invert of the pipeline\nunless the footings are to be placed on competent bedrock.\nIf permanent excavation is proposed beneath the obvert of the pipeline, suitable\nmeans to protect the excavation and proposed retaining structures from seepage or\nother water flow from the pipeline and surrounding subsoil, must be provided. The\ndesign must be prepared by a qualified practicing Structural/Civil Engineer.\nConstruction plans must be approved by the appropriate utility's office (e.g. council,\nSydney Water Corporation) to demonstrate that the development complies with the\nutility's requirements.\nThe applicant must provide written evidence (e.g. compliance certificate, formal\nadvice) of compliance with the requirements of all relevant utility providers (e.g.\nWater, Energy, Telecommunications, Gas).\n(Reason: To ensure protection of Council assets)\nConditions to be satisfied prior to the issue of a Construction Certificate (DACC)\nDACC001 Access (access for people with disabilities)\nAccess for people with disabilities must be provided in accordance with the\nrequirements of the Building Code of Australia, relevant Australian Standards and\nwith regard to the Disability Discrimination Act 1992. Plans shall be notated\ndemonstrating compliance and approved by the Principal Certifying Authority, prior to\nthe issue of a Construction Certificate.\nNote: Disability (Access to Premises - Buildings) Standards 2010 - As of 1 May 2011,\nif access is provided to the extent covered by this Standard, then such access cannot\nbe viewed as unlawful under the Disability Discrimination Act 1992.\n(Reason: To provide equitable access for people(s) with disabilities in accordance\nwith the relevant legislation and Australian Standards)\nDACC002 Access (disabled toilets)\nPlans and details of the disabled toilet/s complying with the relevant Australian\nStandards, the Building Code of Australia, and with regard to the Disability\nDiscrimination Act 1992. Plans shall be notated demonstrating compliance and\napproved by the Principal Certifying Authority, prior to the issue of a Construction\nCertificate.\nNote: Disability (Access to Premises - Buildings) Standards 2010 - As of 1 May 2011,\nif access is provided to the extent covered by this Standard, then such access cannot\nbe viewed as unlawful under the Disability Discrimination Act 1992.\n(Reason: To provide equitable access for people(s) with disabilities in\naccordance with the relevant legislation and Australian Standards)\nDACC007 BASIX commitments\nThe approved BASIX Certificate shall be submitted to the Principal Certifying\nAuthority with the application for a Construction Certificate.\nWhere a change or changes are proposed in the BASIX commitments, the applicant\nmust submit a new BASIX Certificate to the Principal Certifying Authority and\nCouncil. If any proposed change in the BASIX commitments is inconsistent with the\ndevelopment consent the applicant will be required to submit a modification to the\ndevelopment consent to Council under Section 96 of the Environmental Planning and\nAssessment Act 1979.\nAll commitments in the BASIX Certificate must be shown on the plans accompanying\nthe Construction Certificate.\n(Reason: Statutory compliance)\nDACC008 Bicycle storage provision\nOn-site provision for bicycle storage facilities shall be in accordance with the\nStrathfield Consolidated Development Control Plan 2005. Details demonstrating\ncompliance shall be submitted to the Principal Certifying Authority, prior to the issue\nof a Construction Certificate.\n(Reason: Compliance with SCDCP 2005 and to encourage sustainable\ntransport options)\nDACC010 Building Code of Australia (compliance with)\nAll architectural drawings, specifications and related documentation shall comply with\nthe Building Code of Australia (BCA). All work must be carried out in accordance with\nthe requirements of the Building Code of Australia (BCA).\nIn the case of residential building work for which the Home Building Act 1989\nrequires there to be a contract of insurance in force in accordance with Part 6 of that\nAct, such a contract of insurance is to be in force before any building work authorised\nto be carried out by the consent commences.\nDetails demonstrating compliance with this condition are to be submitted to the\nPrinciple Certifying Authority, prior to issue of the Construction Certificate.\n(Reason: This is a 'prescribed' condition under clause 98(1) of the Environmental\nPlanning and Assessment Regulation 2000)\nDACC011 Car parking (basement car parking requirements)\nDetails demonstrating compliance with the following is to be submitted to the\nPrincipal Certifying Authority, prior to issue of the Construction Certificate:\n(i) Minimal internal clearance of the basement is 2.2m in accordance\nwith BCA requirements.\n(ii) Driveways shall comply with Australian/New Zealand Standard\nAS/NZS 2890. 1:2004 - Parking facilities - Off-street car parking and\nachieve a maximum gradient of 1:4.\n(iii) Basement entries and ramps/driveways within the property are to be\nno more than 3.5m wide.\n(iv) Provision of pump-out systems and stormwater prevention shall be in\naccordance with Council's Stormwater Management Guide.\n(Reason: To ensure suitable development)\nDACC012 Car parking (disabled car parking spaces)\nSeven (7) of the car parking spaces provided as part of the total requirement shall be\nreserved for disabled persons. These spaces shall be a minimum of 3.2m wide x\n5.5m long and located near pedestrian access routes designed for disabled persons.\nEach space shall be clearly marked as such.\nCar parking for people with disabilities shall be provided in accordance with the\nBuilding Code of Australia, relevant Australian Standards and with regard to the\nDisability Discrimination Act 1992. Prior to the issue of a Construction Certificate, the\nplans shall be notated to demonstrate compliance.\nThe above details shall be submitted to and approved by the Principal\nCertifying Authority prior to the issue of a Construction Certificate.\n(Reason\n: To ensure adequate parking for persons with a disability)\nDACC013 Car parking (requirements for multiple use buildings)\nThe following car parking and service vehicle requirements apply:-\n(i) (54) car spaces shall be provided on the development site. This shall\nconsist of:\n 38 residential spaces;\n 8 visitor spaces;\n 8 business/commercial/retail premises spaces;\n(ii) All car spaces shall be allocated and marked according to this\nrequirement.\n(iii) If the development is to be strata subdivided, the car park layout\nmust reflect the above allocation and thereafter be regarded as part\nof the entitlement of that strata lot.\n(iv) Under no circumstances shall parking spaces be sold, let or\notherwise disposed of for use other than in accordance with this\ncondition.\n(v) Each car parking space shall have minimum dimensions in\naccordance with the relevant Australian Standard and be provided\non-site in accordance with the approved plans.\n(vi) The parking bays shall be delineated by line marking.\n(vii) Visitor spaces shall be clearly line marked and/or signposted and\nshall only be used by persons visiting residents of the property or\ncommercial/business/retail premises located within the development.\nVisitor spaces shall not be allocated as permanent residential parking\nspaces. Access to visitor parking spaces shall not be restricted\nwithout development approval and a sign shall be erected at the\nvehicular entrance indicating the availability of visitor parking.\n(viii) The following traffic control measures shall be implemented on site:-\n Signage indicating 'Entry Only' shall be prominently displayed\nat the entrance to the development.\n Signage indicating 'Exit Only' shall be prominently displayed at\nthe exit to the development.\n One-Way directional arrows shall be painted on the driveway\npavement to indicate the required vehicular directional\nmovement through the car parking area.\nDetails demonstrating compliance with this condition shall be submitted to and\napproved by the Principal Certifying Authority, prior to the issue of a Construction\nCertificate.\n(Reason: To ensure car parking provision in accordance with this consent)\nDACC015 Car parking (vehicular access ramps)\nVehicular access ramps shall comply with the provisions of AS/NZS 2890.1:2004.\nPlans to be submitted shall contain the following details:\n(i) Longitudinal section along the extreme wheel paths of each\ndriveway/access ramp at a scale of 1:25 demonstrating compliance\nwith the scraping provisions of AS/NZS 2890.1:2004. It shall include\nall levels and grades, including those levels stipulated as boundary\nlevels, both existing and proposed. It shall extend from the centre-line\nof the roadway through to the parking area.\n(ii) Sections showing the clearance to the underside of any overhead\nstructure (minimum headroom requirements 2200mm minimum for\nstandard headroom clearance or 2400mm where disabled access\nprovisions are to be provided) demonstrating compliance with the\nprovisions of AS/NZS 2890.1:2004.\n(iii) Longitudinal section along the gutter line showing how it is intended\nto transition the vehicular crossing into the existing kerb and gutter.\nBoundary levels shall generally run parallel with the kerb levels.\n(iv) Location of verge trees, street furniture and service installations.\n(v) Superimposition of vehicle turning circles for access into parking\nspaces.\n(vi) Certification that the design complies with AS/NZS 2890.1:2004 by a\nQualified Engineer.\nThe certification referred to in (vi) above shall be submitted to the Principal Certifying\nAuthority prior to the issue of a Construction Certificate (for the design) and to the\nPrincipal Certifying Authority prior to the issue of any Occupation Certificate for the\n'as-built works'.\n(Reason: To ensure adequate vehicular access can be achieved)\nDACC016 Car parking (compliance with AS/NZS 2890.1:2004)\nCar parking dimensions must comply with the Australian/New Zealand Standard\nAS/NZS 2890.1:2004 - Parking facilities - Off-street car parking. Details\ndemonstrating compliance are to be submitted to the Principal Certifying Authority,\nprior to the issue of a Construction Certificate.\n(Reason: To ensure compliance with Australian Standards relating to parking of\nvehicles)\nDACC017 Car parking (vehicular circulation, aisle and ramp widths)\nThe aisle widths, internal circulation, ramp widths and grades of the car park shall\ncomply with the Roads and Traffic Authority Guidelines and ASNZS 2890.1:2004 -\nOff-Street Car Parking Code.\nVehicular manoeuvring paths are to be prepared demonstrating that all vehicles can\nenter or depart the site in a forward direction without encroaching on required car\nparking spaces.\n(Reason: To ensure compliance with Australian Standards relating to manoeuvring,\naccess and parking of vehicles)\nDACC019 Commencement of works (no works until a CC is obtained)\nBuilding works or excavation must not commence until a Construction\nCertificate has been issued, a Principal Certifying Authority has been appointed,\nand a Notice of Commencement has been issued.\n(Reason: To ensure compliance with statutory provisions namely\n‘commencement of erection of building’ pursuant to section 81A(2) of the EP&A\nAct 1979)\nMODIFIED: DA2016.143.7 3 May 2023\nDACC020 Construction and environmental management plan\nThe applicant must prepare and submit a Construction and Environmental\nManagement Plan (CEMP) to the Principal Certifying Authority, including:\n(i) Detailed information on any approvals required from other\nauthorities prior to or during construction.\n(ii) Traffic management, including details of:\n ingress and egress of vehicles to the site;\n management of loading and unloading of materials;\n the location of heavy vehicle parking off-site; and\n designated routes for vehicles to the site.\n(iii) The proposed areas within the site to be used for a builder's site\noffice and amenities, the storage of excavated material, construction\nmaterials and waste containers during the construction period.\n(iv) Erosion and sediment control, detailing measures and procedures\nconsistent with the requirements of Council's guidelines for managing\nstormwater, including:\n the collection and treatment of stormwater and wastewater\ngenerated on site prior to discharge; and\n procedures to prevent run-off of solid material and waste from\nthe site.\n(v) Waste management, including:\n details of the types and estimated volumes of waste materials\nthat will be generated;\n procedures for maximising reuse and recycling of construction\nmaterials; and\n details of the off-site disposal or recycling facilities for\nconstruction waste.\n(i) Dust control, outlining measures to minimise the generation and\noffsite transmission of dust and fine particles, such as watering or\ndamp cloth fences.\n(ii) A soil and water management plan, which includes:\n measures to minimise the area of soils exposed at any one\ntime and conserve top soil;\n identification and protection of proposed stockpile locations;\n preservation of existing vegetation and revegetation;\n measures to prevent soil, sand, sediments leaving the site in an\nuncontrolled manner;\n measures to control surface water flows through the site in a\nmanner that diverts clean run-off around disturbed areas,\nminimises slope gradient and flow distance within disturbed\nareas, ensures surface run-off occurs at non-erodible\nvelocities, and ensures disturbed areas are promptly\nrehabilitated;\n details of sediment and erosion control measures in place\nbefore work commences;\n measures to ensure materials are not tracked onto the road by\nvehicles entering or leaving the site; and\n details of drainage to protect and drain the site during works.\n(iii) Asbestos management procedures:\n Anyone who removes, repairs or disturbs bonded or a friable\nasbestos material must hold a current removal licence from\nWorkcover NSW holding either a Friable (Class A) or a Non-\nFriable (Class B) Asbestos Removal License whichever applies\nand a current WorkCover Demolition License where works\ninvolve demolition. To find a licensed asbestos removalist\nplease see www.workcover.nsw.gov.au\n Removal of asbestos by a person who does not hold a\nClass A or Class B asbestos removal license is permitted if\nthe asbestos being removed is 10m^ or less of non-friable\nasbestos (approximately the size of a small bathroom). Friable\nasbestos materials must only be removed by a person who\nholds a current Class A asbestos license.\n Before starting work, a work site-specific permit approving each\nasbestos project must be obtained from Workcover NSW. A\npermit will not be granted without a current Workcover licence.\nAll removal, repair or disturbance of or to asbestos material\nmust comply with the following:\n The Work Health and Safety Act 2011;\no The Work Health and Safety Regulation 2011;\no How to Safety Remove Asbestos Code of Practice -\nWorkCover 2011; and\no Safe Work Australia Code of Practice for the\nManagement and Control of Asbestos in the\nWorkplace.\n Following completion of asbestos removal works undertaken by\na licensed asbestos removalist reoccupation of a workplace\nmust not occur until an independent and suitably licensed\nasbestos removalist undertakes a clearance inspection and\nissues a clearance certificate.\n The developer or demolition contractor must notify adjoining\nresidents at least two (2) working days (i.e. Monday to Friday\nexclusive of public holidays) prior to the commencement of\nasbestos removal works. Notification is to include, at a\nminimum:\no the date and time when asbestos removal works will\ncommence;\no the name, address and business hours contact\ntelephone number of the demolisher, contractor and/or\ndeveloper;\no the full name and license number of the asbestos\nremovalist/s; and\no the telephone number of WorkCover's Hotline 13 10\n50 o warning signs informing all people nearby that\nasbestos removal work is taking place in the area.\nSigns should be placed at all of the main entry points\nto the asbestos removal work area where asbestos is\npresent. These signs should be weatherproof,\nconstructed of light-weight material and adequately\nsecured so they remain in prominent locations. The\nsigns should be in accordance with AS 1319-1994\nSafety signs for the occupational environment for size,\nillumination, location and maintenance; and\no appropriate barricades installed as appropriate to\nprevent public access and prevent the escape of\nasbestos fibres. Barricades must be installed prior to\nthe commencement of asbestos removal works and\nremain in place until works are completed.\n(Reason: Safety, amenity and protection of public infrastructure and the environment)\nDACC021 Dilapidation report (pre-commencement)\nSubject to access being granted, a pre-commencement Dilapidation Report is to be\nundertaken on all adjoining properties, which in the opinion of a suitably qualified\nengineer, could be potentially affected by the construction of the project. The\nDilapidation Report shall be carried out prior to the issue of a Construction Certificate.\nThe Dilapidation Report is to be prepared by a suitably Qualified Engineer with\ncurrent Corporate Membership with the Institution of Engineers, Australia or\nGeotechnical Practitioner. The report shall include a photographic survey of adjoining\nproperties detailing the physical condition of those properties, both internally and\nexternally, including walls, ceilings, roof, structural members and other such items.\nIf access for undertaking the dilapidation survey is denied by an adjoining owner, the\napplicant must demonstrate, in writing, to Council's satisfaction attempts have been\nmade to obtain access and/or advise the affected property owner of the reason for\nthe survey and these attempts have been unsuccessful. Written concurrence must be\nobtained from Council in such circumstances.\nThe Report shall cover structural and geotechnical factors likely to arise from the\ndevelopment. A copy of this Report shall be submitted to Council as a record. The\nperson having the benefit of the development consent must, at their own cost, rectify\nany damage caused to other properties during the construction of the project.\n(Reason: To ensure no damage to adjoining properties occurs)\nDACC022 Driveway width (multi-unit development)\nThe internal driveway must be a minimum 5.50m wide (clear width) for the first 6\nmetres inside the property so as to allow entering & exiting vehicles to pass within the\nsite. Should the driveway narrow after this point it is then to be designed with a\nminimum 1.5m x 1.5m splay to allow the passing to work. Details demonstrating\ncompliance shall be submitted to the Principal Certifying Authority, prior the issue of a\nConstruction Certificate.\n(Reason: Safety and traffic management)\nDACC024 Erosion and sedimentation control plan\nAn Erosion and Sediment Control Plan is to be prepared where construction or\nexcavation activity requires the disturbance of the soil surface and existing\nvegetation. Details including drawings and specifications must provide adequate\nmeasures for erosion and sediment control to ensure:\n(i) Compliance with the approved Soil and Water Management Plan.\n(ii) Removal or disturbance of vegetation and top soil is confined to\nwithin 3m of the approved building area (no trees to be removed\nwithout approval).\n(iii) All uncontaminated run-off is diverted around cleared or disturbed\nareas.\n(iv) Silt fences or other devices are installed to prevent sediment and\nother debris escaping from the cleared or disturbed areas into\ndrainage systems or waterways.\n(v) All erosion and sediment controls are fully maintained for the duration\nof demolition/ development works.\n(vi) Controls are put into place to prevent tracking of sediment by\nvehicles onto adjoining roadways.\n(vii) All disturbed areas are rendered erosion-resistant by turfing,\nmulching, paving or similar.\n(viii) All water pumped or otherwise removed from excavations or\nbasement areas is filtered to achieve suspended solids/non filterable\nresidue levels complying with the Australian Water Quality guidelines\nfor Fresh and Marine Waters.\n(ix) Pumped or overland flows of water are discharged so as not to\ncause, permit or allow erosion before the commencement of work\n(and until issue of the occupation certificate).\nDetails of the proposed soil erosion and sedimentation controls are to be submitted to\nthe Principal Certifying Authority with the Construction Certificate Application. Under\nno circumstances are any works to commence, prior to these details being approved\nby the Principal Certifying Authority and the controls being in place on the site.\n(Reason: Environmental protection)\nDACC025 Excavation (affecting adjoining land)\nIf an excavation associated with the approved development extends below the level\nof the base of the footings of a building on an adjoining allotment of land, the person\nhaving the benefit of the development consent must, at the person's own expense,\ncomply with the requirements of clause 98E of the Environmental Planning and\nAssessment Regulation 2000, including:\n(i) protect and support the adjoining premises from possible damage\nfrom the excavation, and\n(ii) where necessary, underpin the adjoining premises to prevent any\nsuch damage.\nThe condition referred to in subclause (i) does not apply if the person having the\nbenefit of the development consent owns the adjoining land or the owner of the\nadjoining land has given consent in writing to that condition not applying. Details shall\nbe submitted to the Principal Certifying Authority, prior to the issue of a Construction\nCertificate.\n(Reason: Structural safety)\nDAGC027 Excavation (shoring)\nWhere any shoring for excavation is to be located on or is supporting\nCouncil's property, or any adjoining private property, engineering drawings\nand specifications certifying the shoring will be adequate for their intended\npurpose and must be submitted to the Council/Principal Certifying Authority\nfor approval with the Construction Certificate. The documentation prepared\nand certified by an appropriately qualified and practicing structural engineer is\nto show all details, including the extent of encroachment and the method of\nremoval and de-stressing of shoring elements. A copy of this documentation\nmust be provided to the Council for record purposes at the time of\nConstruction Certificate application.\n(Reason: To ensure the protection of existing public infrastructure and\nadjoining properties)\nDACC030 Fire safety schedule\nA Fire Safety Schedule specifying the fire safety measures (both current and\nproposed) which should be implemented in the building premises must be\nsubmitted with the Construction Certificate application, in accordance with\nPart 9 of Clause 168 of the Environmental Planning and Assessment\nRegulation 2000.\nNote: A Construction Certificate cannot be issued until a Fire Safety\nSchedule is received.\n(Reason: Compliance with the Environmental Planning and Assessment Act\n1979)\nDACC036 Hoardings\nA Hoarding Application for the erection of a Class A (fence type) or Class B\n(overhead type) hoarding along the street frontage(s) complying with WorkCover\nrequirements must be obtained.\nThe relevant application form shall be submitted to Council with a footpath occupancy\nfee based on the area of footpath to be occupied according to Council's Schedule of\nFees and Charges, and the application shall be approved before the commencement\nof work.\nA Public Risk Insurance Policy with a minimum cover of $20 million in relation to the\noccupation of and works within Council's road reserve, for the full duration of the\nproposed works, must be obtained with a copy also provided to Council.\nThe Policy is to note Council as an interested party. The copy is to be provided\nto\nCouncil, prior to the issue of a Construction Certificate.\n(Reason: Public safety)\nDACC037 Landscaping (landscape plan required)\nA landscape plan prepared by a qualified landscape architect or landscape\nconsultant to a scale of 1:100 or 1:200, conforming to all relevant conditions of\nconsent is to be submitted to the satisfaction of the Principal Certifying Authority with\nthe Construction Certificate application.\nThe plan must include the following information:\n(i) details demonstrating compliance with SCDCP 2005 in relation to\nlandscaping requirements;\n(ii) location of all existing and proposed landscape features including\nmaterials to be used;\n(iii) all trees to be retained, removed or transplanted;\n(iv) existing and proposed finished ground levels;\n(v) top and bottom wall levels for both existing and proposed retaining\nand free standing walls; and\n(vi) a detailed plant schedule which includes proposed species listed by\nbotanical (genus and species) and common names, quantities of\neach species, pot sizes and the estimated size at maturity. A\nminimum of 25% of species shall be locally sourced indigenous\nspecies. Species shall be predominantly selected from Council's\nRecommended Tree List.\nConsideration within the design should be given to the scale of planting in proportion\nto the proposed development, consistency with the existing landscape character of\nthe area, potential views, solar access and privacy for neighbouring development.\n(Reason: Landscape quality)\nDACC038 Landscaping (maintenance strategy)\nTo ensure the survival of landscaping following works, a landscape maintenance\nstrategy for the owner/occupier to administer over a 12 month establishment period\nfollowing the issue of the Occupation Certificate shall be prepared and provided to\nthe satisfaction of the Principal Certifying Authority with the Construction Certificate\napplication. The strategy is to address maintenance issues such as, but not limited to\nplant survival, irrigation, soil testing, weeding, staking, fertilizing, remedial pruning\nand plant replacement.\n(Reason: Ensure landscape survival)\nDACC039 Landscaping (on slab)\nTo ensure the site landscaping thrives, the on slab landscaping shown on the\napproved landscaping plan is to be designed to include a minimum soil depth of\n650mm for shrubs and trees; and 300mm for grass and ground covers. Adequate\ndrainage provision and a permanent, automatic irrigation system conforming to\nSydney Water requirements shall be included. Details demonstrating compliance\nshall be submitted to the Principal Certifying Authority with the Construction\nCertificate application.\n(Reason: Ensure landscape survival)\nDACC045 Privacy (obscure glazing in wet areas)\nAll bathroom, ensuite and toilet windows shall be installed with obscure glazing. Plans\nshall be notated accordingly and details demonstrating compliance submitted to the\nPrincipal Certifying Authority, prior to the issue of a Construction Certificate.\n(Reason: Privacy amenity)\nDACC046 Privacy (measures to be complied with)\nPrior to the issue of a Construction Certificate, plans are to be amended to include\nthe following privacy measures:\n(a) The eastern facing bathroom windows of units 103, 204, 304, 404, 504\nand 604 shall be provided as highlight windows with a minimum sill\nheight of 1.7m above finished ground level and be fitted with obscure\nglazing.\n(Reason: Privacy amenity)\nMODIFIED: DA2016.143.6 3 May 2024\nDACC050 Section 94 contributions (direct contributions plan)\nIn accordance with the provisions of Section 94(1 )(b) of the Environmental Planning\nand Assessment Act 1979 and the Strathfield Direct Development Contributions Plan\n2010-2030, a contribution in the form of cash, cheque or credit card (financial\ntransaction fee applies) shall be paid to Council for the following purposes:\nProvision of Community Facilities $81,615.33\nProvision of Major Open Space $352,655.95\nProvision of Local Open Space $229,974.10\nProvision Roads and Traffic Management $8,961.57\nAdministration $6,664.10\n____________________________________________________\nTOTAL $679,871.04\nThe total amount of the contribution is valid as at the date of determination and is\nsubject to quarterly indexation. Contributions shall be indexed at the time of payment\nin accordance with clause 2.14 of the Strathfield Direct Development Contributions\nPlan 2010-2030.\nContributions must be receipted by Council and submitted to the Accredited Certifier,\nprior to the issue of any Construction Certificate.\nPlease present a copy of this condition when paying the contribution at the Customer\nService Centre so that it can be recalculated.\nNote: A copy of Strathfield Council's Section 94 Direct Development Contributions\nPlan may be downloaded from Council's website.\n(Reason: To enable the provision of public amenities and services\nrequired/anticipated as a consequence of increased demand resulting from the\ndevelopment)\nDACC052 Security payment (damage deposit for Council\ninfrastructure)\nA security payment of $4,127.00 in the form of cash, bank guarantee, cheque or\ncredit card (financial transactions fees apply) shall be paid to Council prior to the\nissue of a Construction Certificate. The security payment is GST inclusive and\ncomprises the following:\nRefundable works bond $4,000.00\nNon-refundable administration fee ($127/bond) $127.00\n_______________________________________________\nTOTAL $4,127. 00\nThe security payment covers the following matters and will be released upon\nsatisfactory completion of these items:\n(i) road and stormwater drainage works in roadways and public areas;\n(ii) installation and maintenance of sediment control measures for the\nduration of construction activities;\n(iii) tree final inspection to ensure that Council's street trees have been\nretained, protected or replanted in accordance with conditions of\nconsent and/or Arborists' report for the post final inspection twelve\n(12) month period; and\n(iv) inspection that no damage has occurred to or building\ndebris/materials have been left on Council land including the\nfootpath, nature strip, kerb and gutter.\nNote: The security bond may be used to recover the costs incurred by Council in\ncleaning and restoring the land to its original condition.\n(Reason: Protection of Council infrastructure)\nDACC054 Stormwater (silt arresters and gross pollutant traps)\nSilt and gross pollutant traps shall be fitted in all new stormwater pits and designed in\naccordance with Council's specification for the management of stormwater. Details\ndemonstrating compliance are to be submitted to the Principal Certifying Authority,\nprior to the issue of a Construction Certificate.\n(Reason: Environmental protection)\nDACC059 Works permit\nA Works Permit shall be obtained from Strathfield Council at least five (5) working\ndays prior any work (including demolition, excavation and the erection of site\nfencing/hording). The approved Works Permit and any approved Construction Traffic\nManagement Plan must be complied with at all times until all demolition, building,\nengineering and construction work associated with the development has been\ncompleted. The permit must be retained on site at all times.\n(Reason: Council requirement)\nDACC060 Works (within the road reserve)\nDetailed drawings including long and short sections and specifications of all works\nwithin existing roads (including but not limited to structures, road works, driveway\ncrossings, footpaths and stormwater drainage) shall be submitted to and approved by\nCouncil under Section 138 of the Roads Act 1993 and all fees and charges paid, prior\nto the issue of a Construction Certificate.\nDetailed drawings and specifications are to be prepared and certified by an\nappropriately qualified Civil Engineer.\nUpon completion of the works, the Applicant is to provide to Council with electronic\ncopies of 'Work as Executed Plans'. The plans are to show relevant dimensions and\nfinished levels and are to be certified by a surveyor.\nThe Applicant is to provide to Council, in an approved format, details of all public\ninfrastructure created as part of the works.\nAll civil engineering works adjacent/near/outside 131 Parramatta Road, Homebush\nare to be fully supervised by Council. A maintenance period of six (6) months shall\napply to the work, after it has been completed and approved. In that period the\nApplicant shall be liable for any part of the work which fails to perform in the manner\noutlined in Council's specifications, or as would reasonably be expected under the\ndesign conditions.\n(Reason: To ensure compliance of engineering works/Council assets are constructed\nto acceptable standards for engineering works)\nDACC061 Traffic (construction traffic management plan)\nA Construction Traffic Management Plan (CTMP) is to be prepared by an\nappropriately qualified Traffic Management Consultant and submitted to and\napproved by Council's Engineering Section, prior to the commencement of any works\nincluding demolition.\nThe following matters should be addressed in the CTMP (where applicable):\n(i) description of the demolition, excavation and construction works;\n(ii) site plan/s showing the site, roads, footpaths, site access points and\nvehicular movements;\n(iii) size, type and estimated number of vehicular movements (including\nremoval of excavated materials, delivery of materials and concrete to\nthe site);\n(iv) proposed route(s) from the arterial (state) road network to the site\nand the proposed route from the site back to the arterial road\nnetwork;\n(v) impacts of the work and vehicular movements on the road network,\ntraffic and pedestrians and proposed methods to safely manage\npedestrians and construction related vehicles in the frontage\nroadways;\n(vi) any Traffic Control Plans (TCP'S) proposed to regulate traffic and\npedestrian movements for construction activities (such as concrete\npours, crane installation/removal etc.);\n(vii) proposed hours of construction related activities and vehicular\nmovements to and from the site;\n(viii) current/proposed approvals from other Agencies and Authorities\n(including Roads and Maritime Services, Police and State Transit\nAuthority);\n(ix) any activities proposed to be located or impact upon Council's\nroad, footways or any public place;\n(x) measures to maintain public safety and convenience;\n(xi) any proposed road and/or footpath closures;\n(xii) turning areas within the site for construction and spoil removal\nvehicles, allowing a forward egress for all construction vehicles\non\nthe site;\n(xiii) locations of work zones (where it is not possible for\nloading/unloading to occur on the site) in the frontage roadways\naccompanied by supporting documentation that such work zones\nhave been approved by the Local Traffic Committee and Council;\n(xiv) location of any proposed crane and concrete pump and truck\nstanding areas on and off the site (and relevant approvals from\nCouncil for plant on road);\n(xv) a dedicated unloading and loading point within the site for all\nconstruction vehicles, plant and deliveries;\n(xvi) material, plant and spoil bin storage areas within the site, where all\nmaterials are to be dropped off and collected;\n(xvii) on-site parking area for employees, tradespersons and construction\nvehicles as far as possible;\n(xviii) proposed areas within the site to be used for the storage of\nexcavated material, construction materials and waste and recycling\ncontainers during the construction period; and\n(xix) how it is proposed to ensure that soil/excavated material is not\ntransported onto surrounding footpaths and roadways.\n(Reason: To mitigate traffic impacts on the surrounding area during the construction\nperiod)\nDACC063 Utilities and telecommunications (electricity substation)\nAny required electricity substation must be located within the boundaries of the site.\nDocumentary evidence of compliance with the energy authority's requirements,\nincluding correspondence from the energy authority is to be provided to the Principal\nCertifying Authority, prior to the issue of a Construction Certificate.\nNote: Where an electricity substation is required but no provision has been made to\nplace it within the approved building or its site and no details are provided on the\napproved development consent plans, a section 96 application is required to be\nsubmitted to Council for approval of an appropriate location for the required electricity\nsubstation.\n(Reason: Access to utility)\nDACC065 Vehicular crossings (works permit for construction of)\nFull-width, heavy-duty concrete vehicular crossing(s) shall be provided across the\nfootpath at the entrance(s) and/or exit(s) to the site and designed in accordance with\nCouncil's guidelines and specifications. In this regard, a Works Permit is to be\nobtained (available from Council's Customer Services Centre or downloaded from\nCouncil's website), and the appropriate fees and charges paid, prior to the lodgement\nof a Construction Certificate.\n(Reason: To ensure appropriate access to the site can be achieved)\nDACC066 Ventilation systems (mechanical)\nThe mechanical ventilation system is to comply with the following:\n(i) The Building Code of Australia;\n(ii) Protection of the Environment Operations Act 1997; and\n(iii) Australian Standard AS1668-1991.\nIn addition, odour control measures, such as activated carbon or catalytic oxidisers,\nmust be used to treat ventilation gases prior to discharge. The method of odour\ncontrol must be designed by a suitably qualified mechanical ventilation engineer.\nDetails demonstrating compliance with the above are to be submitted to the Principal\nCertifying Authority, prior to the issue of a Construction Certificate.\n(Reason: To ensure the mechanical ventilation system complies with the relevant\nrequirements/standards).\nDACC067 Waste management plan\nA Waste Management Plan (WMP) is to be provided in accordance with Part H of\nStrathfield Consolidated Development Control Plan 2005. All requirements of the\napproved Waste Management Plan must be implemented during demolition,\nconstruction and on-going use of the premises.\nThe WMP must identify the types of waste that will be generated and all proposals to\nre-use, recycle or dispose of the waste. The WMP is to be submitted to the Principal\nCertifying Authority, prior to issue of the Construction Certificate.\n(Reason: To ensure appropriate management of waste)\nDACC068 Waste (separate areas for mixed-use developments)\nThe building must include not less than two independently designated areas or\ngarbage rooms for commercial and for residential occupants; to keep commercial\nwaste and recycling separate to residential waste and recycling.\n(Reason: To ensure the appropriate separation and collection of waste generated by\ncommercial and residential activities)\nDACC069 Waste (garbage rooms or grease arrester rooms)\nGarbage rooms or grease arrester rooms must be constructed of solid material:\ncement rendered and steel trowelled to a smooth even surface. The door to the\ngarbage room is to be designed and constructed to ensure the room is vermin proof\nand can be opened from the inside at all times. The garbage room is to be ventilated\nto the external air by natural ventilation or an approved air handling exhaust system.\n(Reason: To keep garbage rooms in a clean and sanitary condition to protect public\nhealth)\nDACC072 Water heating systems (location of)\nWater heating systems shall be located so as not to be visible from public places and\nthe ground level of adjoining properties. Details (type and location) of the water\nheaters shall be submitted to and approved by the Principal Certifying Authority, prior\nto the issue of a Construction Certificate.\n(Reason: To maintain streetscape character)\nDACC073 Works zone (approval by Council's traffic committee)\nAn application for a 'Works Zone' must be submitted to and approved by the\nStrathfield Council Traffic Committee prior to the commencement of any site work\nincluding demolition).\nThe suitability of the proposed length and duration of the Works Zone is to be\ndemonstrated in the application for the Works Zone. The application for the Works\nZone must be submitted to Council at least six (6) weeks prior to the commencement\nof work on the site to allow for assessment and tabling of agenda for the Strathfield\nCouncil Traffic Committee.\nThe requirement for a Works Zone may be varied or waived only if it can be\ndemonstrated in the Construction Traffic Management Plan (to the satisfaction of\nCouncil) that all construction related activities (including all loading and unloading\noperations) can and will be undertaken wholly within the site. The written approval of\nCouncil must be obtained to provide a Works Zone or to waive the requirement to\nprovide a Works Zone prior to the commencement of any site work.\n(Reason: Council requirement)\nConditions to be satisfied prior to the commencement of works (DAPC)\nDAPC001 Appointment of a principal certifying authority\nNo work shall commence in connection with this Development Consent until:\n(i) A construction certificate for the building work has been issued by the\nconsent authority or a Principal Certifying Authority.\n(ii) The person having the benefit of the development consent has\nappointed a principal certifying authority for the building work, and\nnotified the principal certifying authority that the person will carry out\nthe building work as an owner/builder, if that is the case.\n(iii) The principal certifying authority has, no later than 2 days before the\nbuilding work commences:\n notified the Council of his or her appointment, and\n notified the person having the benefit of the development\nconsent of any critical stage inspections and other inspections\nthat are to be carried out in respect of the building work.\n(iv) The person having the benefit of the development consent, if not\ncarrying out the work as an owner-builder, has:\n appointed a principal contractor for the building work who must\nbe the holder of a contractor licence if any residential building\nwork is involved;\n notified the principal certifying authority of such appointment;\nand\n unless that person is the principal contractor, notified the\nprincipal contractor of any critical stage inspections and other\ninspections that are to be carried out in respect of the building\nwork.\n(v) The person having the person having the benefit of the development\nconsent has given at least 2 days notice to the Council of the\nperson's intention to commence the erection of the building.\nNote: If the principal certifying authority is the Council, the nomination will be subject\nto the payment of a fee for the service to cover the cost of undertaking all necessary\ninspections and the issue of the appropriate certificates.\nUnder the Environment Planning and Assessment (Quality of Construction) Act,\n2003, a sign must be erected in a prominent position on the work site showing the\nname, address and telephone number of the principal certifying authority; the name\nof the principal contractor (if any) for the building work and a telephone number at\nwhich that person may be contacted outside working hours. That sign must also state\nthat unauthorised entry is prohibited. The sign must not be removed until all work has\nbeen completed.\n(Reason: Statutory requirement)\nDAPC002 Home building compensation fund\nNo residential building work within the meaning of the Home Building Act 1989 may\ncommence until:\n(i) A contract of insurance in accordance with Part 6 of the Home\nBuilding Act 1989 is entered into and in force, where such a contract\nis required under that Act (this is a prescribed condition of consent\npursuant to clause 981 (b) Environmental Planning and Assessment\nRegulation 2000.\n(ii) The PCA is satisfied that the principal contractor for the work is the\nholder of the appropriate licence and is covered by the appropriate\ninsurance, in each case if required by the Home Building Act 1989\n(unless the work is to be carried Out by an owner builder).\n(iii) If the work is to be carried out by an owner builder, that the owner\nbuilder is the holder of any owner-builder permit required under the\nHome Building Act 1989.\n(iv) Written notice of the following information has been provided to\nCouncil (this is a prescribed condition of consent pursuant to clause\n98B of the Environmental Planning and Assessment Regulation\n2000):\n In the case of work for which a principal contractor is required\nto be appointed:\no the name and licence number of the principal\ncontractor;\nand\no the name of the insurer by which the work is insured\nunder Part 6 of the Home Building Act 1989.\n In the case of work to be done by an owner-builder:\no the name of the owner-builder; and\no if the owner-builder is required to hold an owner builder\npermit under the Home Building Act 1989, the number\nof the owner-builder permits.\nWhere Council is not the PCA, the PCA is responsible for notifying Council of\nthe above matters.\nNote: Where arrangements for doing residential building work change while\nthe work is in progress so that the above information becomes out of date, the\nPCA (where not the Council) must provide Council with written notice of the\nupdated information.\n(Reason: Statutory requirement)\nDAPC003 Notice of commencement\nNo work shall commence until the following details are submitted to Council:\n(i) a Notice of Commencement (form will be attached with issue of a\nConstruction Certificate or available from our website) within two (2)\ndays of the date on which it is proposed to commence works\nassociated with the Development Consent;\n(ii) details of the appointment of a Principal Certifying Authority (either\nCouncil or another Principal Certifying Authority); and\n(iii) details of the name, address and licence details of the Builder.\n(Reason: Statutory requirement)\nConditions to be satisfied during demolition and building works (DADW)\nDADW001 Contaminated land unexpected finds\nIn the instance works cause the generation of odours or uncovering of unexpected\ncontaminants works are to immediately cease, Council is to be notified and a suitably\nqualified environmental scientist appointed to further assess the site.\nThe contaminated land situation is to be evaluated by the supervising environmental\nconsultant and an appropriate response determined in consultation with the\napplicant, which is agreed to by Strathfield Council's Environmental Services\nManager.\nNote: Council may also request that a NSW EPA accredited site auditor is involved to\nassist with the assessment of the contaminated land situation and review any new\ncontamination information. The applicant must also adhere to any additional\nconditions which may be imposed by the accredited site auditor.\n(Reason: To ensure compliance with statutory requirements)\nDADW002 Fill material\nThe only waste derived material which may be received at the development site is:\n(i) Virgin excavated material (within the meaning of the Protection of the\nEnvironment Operations Act 1997), and\n(ii) any other waste-derived material the subject of a resource recovery\nexemption under cl.51A of the Protection of the Environment\nOperations (Waste) Regulation 2005 that is permitted to be used as\nfill material.\nAny (b)-type material received at the development site must be accompanied by\ndocumentation certifying by an appropriately qualified environmental consultant the\nmaterials compliance with the exemption conditions; and this documentation must be\nprovided to the Principal Certifying Authority on\nrequest.\n(Reason: To ensure imported fill is of an acceptable standard for environmental\nprotection purposes)\nDADW005 Heritage (historic relics found during works)\nShould any potentially historic relics be discovered on the site during excavation, all\nexcavation or disturbance to the area is to stop immediately and the Heritage Division\nof the NSW Department of Environment and Heritage should be informed in\naccordance with Section 146 of the Heritage Act 1977. 'Relics' are any deposit,\nartefact, object or material evidence that relates to the settlement of the area that\ncomprises New South Wales, not being Aboriginal settlement, and are of State or\nlocal heritage significance.\nShould any potentially significant Aboriginal material be discovered on the site, all\nexcavation or disturbance of the area is to stop immediately and the Heritage Division\nof the NSW Department of Environment and Heritage is to be informed in accordance\nwith Section 91 of the National Parks and Wildlife Act 1974.\n(Reason: To ensure the proper management and preservation of potentially\nsignificant archaeological material)\nDADW006 Obstruction of public way (not permitted during works)\nThe public way must not be obstructed by any materials, vehicles, refuse, skips or\nthe like, under any circumstances, without the prior approval of Council.\n(Reason: To maintain public access and safety)\nDADW007 Public infrastructure and services\nThe applicant must comply with the requirements (including financial costs) of any\nrelevant utility provider (e.g. Energy Australia, Sydney Water, Telstra, RMS, Council\netc.) in relation to any connections, works, repairs, relocation, replacements and/or\nadjustments to public infrastructure or services affected by the development.\n(Reason: To maintain public infrastructure and/or services)\nDADW010 Site requirements during demolition and construction\nAll of the following are to be satisfied/complied with during demolition, construction\nand any other site works:\n(i) All demolition is to be carried out in accordance with Australian\nStandards AS 2601-2001.\n(ii) Demolition must be carried out by a registered demolition contractor.\n(iii) A single entrance is permitted to service the site for demolition and\nconstruction. The footway and nature strip at the service entrance\nmust be planked out with close boarded, hardwood timber footpath\nprotection pads. The pad shall cover the entire width of the footpath\nopening for the full width of the fence.\n(iv) No blasting is to be carried out at any time during construction of\nthe building.\n(v) Care must be taken during demolition/ excavation/ building/\nconstruction to prevent any damage to adjoining buildings.\n(vi) Adjoining owner property rights and the need for owner's permission\nmust be observed at all times, including the entering onto land for the\npurpose of undertaking works.\n(vii) Any demolition and excess construction materials are to be recycled\nwherever practicable.\n(viii) The disposal of construction and demolition waste must be in\naccordance with the requirements of the Protection of the\nEnvironment Operations Act 1997.\n(ix) All waste on the site is to be stored, handled and disposed of in such\na manner as to not create air pollution (including odour), offensive\nnoise or pollution of land and/or water as defined by the Protection of\nthe Environment Operations Act 1997.\n(x) All excavated material should be removed from the site in the\napproved manner and be disposed of lawfully to a tip or other\nauthorised disposal area.\n(xi) Section 143 of the Protection of the Environment Operations Act\n1997 requires waste to be transported to a place which can lawfully\naccept it. All non-recyclable demolition materials are to be disposed\nof at an approved waste disposal depot in accordance with\nlegislation.\n(xii) All materials on site or being delivered to the site are to generally be\ncontained within the site. The requirements of the Protection of the\nEnvironment Operations Act 1997 must be complied with when\nplacing/stockpiling loose material, disposing of concrete waste, or\nother activities likely to pollute drains or water courses.\n(xiii) Details as to the method and location of disposal of demolition\nmaterials (weight dockets, receipts etc.) should be kept on site as\nevidence of approved methods of disposal and recycling.\n(xiv) Any materials stored on site must be stored out of view or in such a\nmanner so as not to cause unsightliness when viewed from nearby\nlands or roadways.\n(xv) Public footways and roadways adjacent to the site must be fully\nmaintained and cleared of obstructions during construction unless\nprior separate approval from Council is obtained including payment\nof\nrelevant fees.\n(xvi) Building operations such as brick cutting, washing tools or paint\nbrushes, and mixing mortar not be performed on the roadway or\npublic footway or any other locations which could lead to the\ndischarge of materials into the stormwater drainage system.\n(xvii) All site waters during excavation and construction must be contained\non site in an approved manner to avoid pollutants entering into\nwaterways or Council's stormwater drainage system.\n(xviii) Stamped plans, specifications, documentation and the consent shall\nbe available on site at all times during construction.\n(Reason: To ensure that demolition, building and any other site works are undertaken\nin accordance with relevant legislation and policy and in a manner which will be non-\ndisruptive to the local area)\nDADW011 Survey report of approved levels (during and post construction)\nA Survey Certificate to Australian Height Datum shall be prepared by a Registered\nSurveyor as follows:\n(i) At the completion of the first structural floor level prior to the pouring\nof concrete indicating the level of that floor and the relationship of the\nbuilding to the boundaries.\n(ii) At the completed height of the building, prior to the placement of\nconcrete inform work, or the laying of roofing materials.\n(iii) At the completion of the development.\nProgress certificates in response to points (1) through to (3) shall be provided to the\nPrincipal Certifying Authority at the time of carrying out relevant progress inspections.\nUnder no circumstances is work allowed to proceed until such survey information is\nsubmitted to and approved by the Principal Certifying Authority.\n(Reason: To ensure compliance with the approved plans)\nConditions to be satisfied prior to the issue of an Occupation Certificate (DAOC)\nDAOC003 Car parking (surplus vehicular crossings)\nAll surplus vehicular crossings and/or kerb laybacks must be removed and reinstated\nwith concrete kerb and gutter or to the existing edging profile as specified by Council.\nThe nature strip is to be restored and the footpath area reinstated. All of the above\nare to be restored to the satisfaction of Council's Engineer and at full cost to the\napplicant, prior to the issue of any Occupation Certificate.\n(Reason: Maintenance of public infrastructure)\nDAOC004 Car parking (visitor car parking signage)\nA sign shall be erected in a suitable location on the property near the\ndriveway entrance indicating where visitor parking is available on the site.\nSignage shall also be erected above the visitor parking itself. Details\ndemonstrating compliance shall be demonstrated to the Principal Certifying\nAuthority, prior to the issue of any Occupation Certificate.\n(Reason: Adequate access and egress)\nDAOC006 Engineering works (certification of)\nPrior to occupation of the premises, a Work As Executed (WAE) Plan of all\nengineering and/or drainage works is to be submitted to the Principal\nCertifying Authority. The WAE Plan is to be certified by a suitably Qualified\nEngineer, with Corporate Membership standing in the Institution of Engineers\nAustralia and registered on the National Professional Engineers Register\n(NPER) under the appropriate professional category, demonstrating that:\n(i) the stormwater drainage system; and/or\n(ii) the car parking arrangement and area; and/or\n(iii) any related footpath crossing works; and/or\n(iv) the proposed basement pump and well system; and/or\n(v) the proposed driveway and layback; and/or\n(vi) any other civil works\nhave been constructed in accordance with the approved plans and any relevant\nStandards and Council policies/specifications.\nFor major works, such as subdivisions, works within the road reserve requiring\nseparate S138 approval) and as where specified by Council, a Part 4A Certificate will\nbe required. It is strongly recommended that an Engineer supervise all engineering\nrelated works.\nWhere Council is not the Principal Certifying Authority, an electronic copy of the\nabove documents is to be provided to Council, prior to the issue of any Occupation\nCertificate.\n(Reason: Asset management)\nDAOC007 Fire safety (certification)\nA fire safety certificate shall be obtained in accordance with Part 9, Division 4 of the\nEnvironmental Planning and Assessment Regulation 2000, prior to the issue of any\nOccupation Certificate.\nAn fire safety certificate is a certificate issued by the owner of a building to the effect\nthat each essential fire safety measure specified in the current fire safety schedule for\nthe part of the building to which the certificate relates:\n(i) has been assessed by a properly qualified person; and\n(ii) was found, when it was assessed, to be capable of performing to at\nleast the standard required by the current fire safety schedule for the\nbuilding for which the certificate is issued.\nAn interim fire safety certificate must be provided before an interim occupation\ncertificate can be used for a building under Clause 153(2) of the Environmental\nPlanning & Assessment Regulation 2000.\nA final fire safety certificate must be provided before an interim occupation certificate\ncan be used for a building under Clause 153(1) of the Environmental Planning &\nAssessment Regulation 2000.\nA copy of the fire safety certificate and fire safety schedule shall be:\n(i) submitted to Strathfield Council;\n(ii) submitted to the Commissioner of the New South Wales Fire\nBrigade; and\n(iii) prominently displayed in the building.\n(Reason: Fire safety and statutory requirement)\nDAOC013 Occupation of building\nA person must not commence occupation or use (or change of use where an existing\nbuilding) of the whole or any part of a new building (within the meaning of section\n1091-1 (4) of the Act) unless an Interim Occupation Certificate or Final Occupation\nCertificate has been issued in relation to the building or part.\nThe Principal Certifying Authority is required to be satisfied, amongst other things,\nthat;\n(i) all required inspections (including each applicable mandatory critical\nstage inspection) have been carried out; and\n(ii) any preconditions to the issue of the certificate required by a\ndevelopment consent have been met.\nNote: New building includes an altered portion of, or an extension to, an existing\nbuilding.\n(Reason: Statutory requirement)\nDAOC016 DELETED: DA2016.143.6 3 May 2024\nDAOC017 Stormwater (certification of the constructed drainage system)\nThe constructed stormwater system shall be certified by a suitably qualified person,\nin accordance with Council's Stormwater Management Code, prior to the issue of any\nOccupation Certificate.\n(Reason: Adequate stormwater management)\nDAOC018 Stormwater (covenant and restriction as to user for stormwater\ncontrolled systems)\nPrior to the issue of any Occupation Certificate, the applicant shall register a Positive\nCovenant and a Restriction as to User under section 88E and or section 88B of the\nConveyancing Act as appropriate in favour of Council, ensuring the ongoing\nretention, maintenance and operation of the stormwater facility (on-site detention,\npump-out, charged lines, etc.).\nWhere any drainage line or service conduit is to traverse any property other than that\nwhich it serves, an appropriate easement will be required. In this case, the applicant\nshall register an easement no less than 1200mm wide over the proposed drainage\nline or service concurrently with any subdivision registration.\nThe wording on the 88B Instrument is to make reference to the Council file where the\nConstruction plans and the Work As Executed (as built), plans are held. Typical\nwording can be obtained from Council's Specification for the Management of\nStormwater document.\n(Reason: To ensure the on-site detention and/or pump system is maintained to an\nappropriate operational standard)\nDAOC021 Ventilation systems (mechanical)\nThe mechanical ventilation system is to comply with the following:\n(i) The Building Code of Australia;\n(ii) Protection of the Environment Operations Act 1997; and\n(iii) Australian Standard AS1668-1991\nIn addition, odour control measures, such as activated carbon or catalytic oxidisers,\nmust be used to treat ventilation gases prior to discharge. The method of odour\ncontrol must be designed by a suitably qualified mechanical ventilation engineer.\nAt the completion of the installation of the mechanical exhaust ventilation system, a\ncertificate from a practising mechanical engineer shall be submitted\nto the Principal Certifying Authority, prior to issue of the Occupation Certificate\ndemonstrating compliance with the above.\n(Reason: To ensure the mechanical exhaust ventilation system complies with\nthe relevant requirements/standards)\nConditions to be satisfied prior to the issue of a Subdivision Certificate\n(DASC)\nDASC005 Separate application (for strata subdivision)\nThis consent does not imply approval to create a separate title, by subdivision or\notherwise. Should it be intended to subdivide the approved development into strata\ntitle allotments, Council will require the lodgement of a separate development\napplication for consideration.\n(Reason: To ensure compliance with the consent)\nConditions to be satisfied during ongoing use of the premises (DAOU)\nDAOU019 Noise (compliance with acoustic assessment report)\nAll recommendations contained in the approved Noise Assessment Report prepared\nby Acoustic Consulting Engineers Pty Ltd shall be adopted, implemented, and\nadhered to.\nThe Principal Certifying Authority (PCA) shall obtain a statement from an\nappropriately qualified acoustic consultant, certifying that the acoustic mitigation\nmeasures outlined in the above stated report have been suitably incorporated into the\ndevelopment and that relevant, noise criteria have been satisfied prior to the issue of\nany Occupation Certificate.\nAny changes made to the proposal that would alter the acoustic assessment will\nrequire a further acoustic assessment and a copy of this further report shall be\nprovided to Council for approval prior to the commencement of works and any\nrecommendations adopted, implemented, and adhered to.\n(Reason: Noise control and amenity)\nDAOU036 Visitor parking restriction\nAll visitor parking spaces must not at any time be allocated sold or leased to an\nindividual owner/occupier and must be strictly retained as common property by the\nOwners Corporation.\n(Reason: Compliance with approved visitor parking provision)\nDAOU037 Waste and recycling (collection hours)\nThe collection of waste and recycling must only occur between 6.00am and 8.00pm\nweekdays and 9.00am and 5.00pm weekends and public holidays, to avoid noise\ndisruption to the surrounding area.\nGarbage and recycling must not be placed on the kerbside for collection more than\none hour before the scheduled collection time. Bins and containers are to be\nremoved from the kerbside within one (1) hour of collection and returned to the\ndesignated garbage storage area(s).\nThe garbage and recyclable storage area and bins must be adequate to contain the\nvolume and type of garbage and recyclable matter of the food premises.\nAll garbage and recyclable matter must be enclosed in the waste bins with lids\ncompletely closed at all times.\n(Reason: To\nregulate noise and garbage collection arrangements)\nNSW Office of Water - General Terms of Approval\n1. An authorisation shall be obtained from NSW Office of Water for the take of\ngroundwater as part of the activity. Groundwater shall not be pumped or\nextracted for any purpose other than temporary construction dewatering at the\nsite identified in the development application. The authorisation shall be subject\nto a currency period of 12 months from the date of issue and will be limited to the\nvolume of groundwater take identified.\n2. The design and construction of the building must prevent any take of\ngroundwater after the authorisation has lapsed by making any below-ground\nlevels that may be in contact with groundwater watertight for the anticipated life of\nthe building. Waterproofing of below-ground levels must be sufficiently extensive\nto incorporate adequate provision for reasonably foreseeable high water table\nelevations to prevent potential future inundation.\n3. Sufficient permanent drainage shall be provided beneath and around the outside\nof the watertight structure to ensure that natural groundwater flow is not impeded\nand:\n(a) Any groundwater mounding at the edge of the structure shall be at a level\nnot greater than 10% above the level to which the water table might\nnaturally rise in the location immediately prior to the construction of the\nstructure;\n(b) Any elevated water table is more than 1.0m below the natural ground\nsurface existent at the location immediately prior to the construction of the\nstructure; and\n(c) Where the habitable part of the structure (not being footings or\nfoundations) is founded in bedrock or impermeable natural soil then the\nrequirement to maintain groundwater flows beneath the structure is not\napplicable.\n4. Construction methods and material used in and for construction shall be\ndesigned to account for the likely range of salinity and pollutants which may be\ndissolved in groundwater, and shall not themselves cause pollution of the\ngroundwater.\n5. Documentation (referred to as a 'report') comprising measurements, maps, bore\nlogs, calculations, results and justification for various matters related to the\ndewatering process. Information will be required at several stages: prior to\nconstruction commencing (initial report - which will accompany the application for\nauthorisation), at any time when an authorisation renewal is required or a\nsignificant change in activities occurs (intermediate report); and at the\ncompletions of dewatering and related operations (completion report). Reports\nneed to be submitted to DPI Water at the Parramatta Office in a format consistent\nwith electronic retrieval without editing restrictions; raw data should be presented\nin Excel spreadsheets without editing restrictions.\nPrior to excavation\n6. The following shall be included in the initial report:\n(a) measurements of groundwater levels beneath the site from a minimum of\nthree relevant monitoring bores, together with details of the bores used in\nthe assessment including bore logs and three-dimensional identification\ninformation.\n(b) a map of the site and its immediate environs depicting the water table\n(baseline conditions) shown relative to the topography and approved\nconstruction footprint from the surface level and below. An assessment of\nthe potential variation in the water table during the life of the proposed\nbuilding together with a discussion of the methodology and information on\nwhich this assessment is based.\n(c) details of the present and potential groundwater flow paths and hydraulic\ngradients in and around the site; the latter in response to the final\nvolumetric emplacement of the construction.\n(d) a schedule for the ongoing water level monitoring and description of the\nmethodology to be used, from the date of consent until at least two\nmonths after the cessation of pumping. DPI Water prefers that monitoring\nbe undertaken on a continuous basis using automatic loggers in\nboreholes.\nMeasurements of groundwater levels beneath the site from a minimum of\nthree monitoring bores shall be taken. These measurements should be\nincluded in a report provided to the NSW Office of Water in support of the\ndewatering licence application, along with a schedule and indicative level\npredictions for the proposed ongoing water level monitoring from the date of\nconsent until at least two months after the cessation of pumping shall be\nincluded in the report.\n7. The Applicant shall assess the likely impac ts of the dewatering activities on other\ngroundwater users or structures or public infrastructure; this assessment will\ninclude an appropriate bore, spring or groundwater seep census and\nconsiderations relevant to potential subsidence or excessive settlement induced\nin nearby buildings and property, and be documented together with all\ncalculations and information to support the basis of these in the initial report.\n8. Groundwater quality testing of samples taken from outside the footprint of the\nproposed construction, with the intent of ensuring that as far as possible the\nnatural and contaminant hydrochemistry of the potential dewatered groundwater\nis understood, shall be conducted on a suitable number of samples and tested by\na NATA-certified laboratory. Details of the sampling locations and the protocol\nused, together with the test results accompanied by laboratory test certificates\nshall be included in the initial report. An assessment of results must be done by\nsuitably qualified persons with the intent of identifying the presence of any\ncontaminants and comparison of the data against accepted water quality\nobjectives or criteria for the intended dewatering purpose. In the event of adverse\nquality findings, the Applicant must develop a plan to mitigate the impacts of the\nhydrochemistry on the dewatered groundwater and present the details of all\nassessments and plans in the initial report.\n9. Groundwater quality testing generally in accordance with Condition 99, shall be\nundertaken on any anniversary or other renewal or alteration of any dewatering\nauthorisation.\n10. A reasonable estimate of the total volume of groundwater to be extracted shall be\ncalculated and included in the initial report; together with details and calculation\nmethods for the parameters and supporting information to confirm their\ndevelopment or measurement (e.g. permeability predicted by slug-testing, pump-\ntesting or other means).\n11. A copy of a valid consent for the development shall be provided in the initial\nreport.\n12. The method of disposal of pumped water shall be nominated (i.e. reinjection,\ndrainage to the stormwater system or discharge to sewer) and a copy of the\nwritten permission from the relevant controlling authority shall be provided in the\ninitial report. The disposal of any contaminated pumped groundwater (sometimes\ncalled \"tailwater\") must comply with the provisions of the Protection of the\nEnvironment Operations Act 1997 and any requirements of the relevant\ncontrolling authority.\n13. Contaminated groundwater (i.e. above appropriate NEPM 2013 thresholds) shall\nnot be reinjected into any aquifer. The reinjection system design and treatment\nmethods to remove contaminants shall be nominated and included in the initial\nreport and any subsequent intermediate report as necessary. The quality of any\npumped water that is to be reinjected must be demonstrated to be compatible\nwith, or improve, the intrinsic or ambient groundwater in the vicinity of the\nreinjection site.\nDuring excavation\n14. Engineering measures designed to transfer groundwater around the basement\nshall be incorporated into the basement construction to prevent the completed\ninfrastructure from restricting pre-existing groundwater flows.\n15. Piping, piling or other structures used in the management of pumped\ngroundwater shall not create a flooding hazard. Control of pumped groundwater\nis to be maintained at all times during dewatering to prevent unregulated off-site\ndischarge.\n16. Measurement and monitoring arrangements to the satisfaction of DPI Water are\nto be implemented. Weekly records of the volumes of all groundwater pumped\nand the quality of any water discharged are to be kept and a completion report\nprovided after dewatering has ceased. Records of groundwater levels are to be\nkept and a summary showing daily or weekly levels in all monitoring bores\nprovided in the completion report.\n17. Pumped groundwater shall not be allowed to discharge off-site (e.g. adjoining\nroads, stormwater system, sewerage system, etc) without the controlling\nauthorities approval and/or owners consent. The pH of discharge water shall be\nmanaged to be between 6.5 and 8.5. The requirements of any other approval for\nthe discharge of pumped groundwater shall be complied with.\n18. Dewatering shall be undertaken in accordance with groundwater-related\nmanagement plans applicable to the excavation site. The requirements of any\nmanagement plan (such as acid sulfate soils management plan or remediation\naction plan) shall not be compromised by the dewatering activity.\n19. The location and construction of groundwater extraction works that are\ndecommissioned are to be recorded in the completion report. The method of\ndecommissioning is to be identified in the documentation.\n20. Access to groundwater management works used in the activity is to be provided\nto permit inspection when required by the DPI Water under appropriate safety\nprocedures.\nFollowing excavation\n21. Following completion of the dewatering operations, the applicant shall submit to\nDPI Water, Parramatta Office, the completion report which shall include:\n(a) detail of the volume of water taken, the precise periods and location of\nwater taken, the details of water level monitoring in all of the relevant\nbores; and\n(b) a water table map depicting the aquifer's settled groundwater condition\nand a comparison to the baseline conditions; and\n(c) a detailed interpreted hydrogeological report identifying all actual resource\nand third party impacts, including an assessment of altered groundwater\nflows and an assessment of any subsidence or excessive settlement\ninduced in nearby buildings and property and infrastructure.\n22. The completion report is to be assessed by DPI Water prior to any certifying\nagency's approval for occupation or use of the completed construction.\nDYLAN PORTER\nMANAGER PLANNING AND PLACE\nSIGNED on behalf of\nStrathfield Municipal Council\nEND CONDITIONS","stage":"general","stage_basis":"heading","page":8}]});
